import java.util.*;

public class Solution {
    public ListNode detectCycle(ListNode head) {
        Set<ListNode> seen = new HashSet<>();
        ListNode p = head;
        while (p != null) {
            // add 返回 false 说明之前见过，这就是环的入口
            if (!seen.add(p)) return p;
            p = p.next;
        }
        return null;
    }
}

public class Solution {
    public ListNode detectCycle(ListNode head) {
        ListNode slow = head, fast = head;

        // 第一阶段：判环，找到相遇点
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) break;
        }
        // fast 走到头说明无环
        if (fast == null || fast.next == null) return null;

        // 第二阶段：一个回到 head，两个同速走，相遇处即入口
        ListNode p1 = head, p2 = slow;
        while (p1 != p2) {
            p1 = p1.next;
            p2 = p2.next;
        }
        return p1;
    }
}

public class Solution {
    public ListNode detectCycle(ListNode head) {
        if (head == null || head.next == null) return null;

        ListNode slow = head, fast = head, met = null;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                met = slow;
                break;
            }
        }
        if (met == null) return null;   // 无环

        // a = (n-1)L + c：head 与相遇点对环同相位，同速走必在入口相遇
        ListNode p = head, q = met;
        while (p != q) {
            p = p.next;
            q = q.next;
        }
        return p;
    }
}
